import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int, len(inputs))
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

package cache

import (
	"container/list"
)

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity int
	ll       *list.List
	cache    map[string]*list.Element
}

func NewLRU(capacity int) *LRU {
	if capacity <= 0 {
		return nil
	}
	return &LRU{
		capacity: capacity,
		ll:       list.New(),
		cache:    make(map[string]*list.Element),
	}
}

func (c *LRU) Get(key string) (int, bool) {
	if el, ok := c.cache[key]; ok {
		c.ll.MoveToFront(el)
		return el.Value.(*entry).value, true
	}
	return 0, false
}

func (c *LRU) Put(key string, value int) {
	if el, ok := c.cache[key]; ok {
		c.ll.MoveToFront(el)
		el.Value.(*entry).value = value
		return
	}

	if c.ll.Len() >= c.capacity {
		last := c.ll.Back()
		if last != nil {
			c.ll.Remove(last)
			delete(c.cache, last.Value.(*entry).key)
		}
	}

	ent := &entry{key, value}
	c.cache[key] = c.ll.PushFront(ent)
}

func (c *LRU) Len() int {
	return len(c.cache)
}

export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) return [];

  const result: number[][] = [];
  let currentRun: number[] = [];
  let lastRun = -Infinity;

  for (const value of values) {
    if (value === lastRun + 1) {
      currentRun.push(value);
      lastRun = value;
    } else {
      if (currentRun.length > 0) {
        result.push(currentRun);
      }
      currentRun = [value];
      lastRun = value;
    }
  }

  if (currentRun.length > 0) {
    result.push(currentRun);
  }

  return result;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let id = start;

  while (true) {
    if (seen.has(id)) {
      throw new Error("cycle detected");
    }
    seen.add(id);
    chain.push(id);
    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(id);
    if (node.parent === null) {
      break;
    }
    id = node.parent;
  }

  return chain;
}

