import "errors"

type Store interface {
	Get(key) (string, error)
	Put(key, value string) error
}

var ErrTemporary = errors.New("temporary")
var ErrMissing = errors.New("missing")

// Ensure reads key and writes fallback only when the key is missing.
func Ensure(store Store, key, fallback string) (string, error) {
	value, err := store.Get(key)
	if err == nil {
		return value, nil
	}
	if errors.Is(err, ErrMissing) {
		if putErr := store.Put(key, fallback); putErr == nil {
			return fallback, nil
		}
	}
	return "", err
}

package cache

import (
	"container/list"
	"sync"
)

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity int
	items    map[string]*list.Element
	list     *list.List
	mu       sync.Mutex
}

func NewLRU(capacity int) *LRU {
	if capacity <= 0 {
		return nil
	}
	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		list:     list.New(),
	}
}

func (c *LRU) Get(key string) (int, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if element, ok := c.items[key]; ok {
		c.list.MoveToFront(element)
		return element.Value.(*entry).value, true
	}
	return 0, false
}

func (c *LRU) Put(key string, value int) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if element, ok := c.items[key]; ok {
		c.list.MoveToFront(element)
		element.Value.(*entry).value = value
		return
	}

	if c.list.Len() >= c.capacity {
		last := c.list.Back()
		if last != nil {
			c.list.Remove(last)
			delete(c.items, last.Value.(*entry).key)
		}
	}

	e := c.list.PushFront(&entry{key, value})
	c.items[key] = e
}

func (c *LRU) Len() int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return len(c.items)
}

